package com.shopsphere.service;
import com.shopsphere.dto.AuthDtos.RegisterRequest; import com.shopsphere.entity.User; import com.shopsphere.repository.*; import com.shopsphere.security.JwtService; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.password.PasswordEncoder; import static org.mockito.Mockito.*;
class AuthServiceTest { @Mock UserRepository users; @Mock PasswordEncoder encoder; @Mock JwtService jwt; @Mock CartRepository carts; AuthService service; @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new AuthService(users,encoder,jwt,carts);} @Test void rejectsDuplicateEmail(){when(users.existsByEmailIgnoreCase("a@b.com")).thenReturn(true);Assertions.assertThrows(RuntimeException.class,()->service.register(new RegisterRequest("A","a@b.com","password123")));} }
